// src/i18n/format.ts
var PLACEHOLDER = /\{([a-zA-Z0-9_]+)(?:\|([^|}]*)\|([^}]*))?\}/g;
var FRENCH_PLURAL = (count) => Math.abs(count) < 2 ? "one" : "other";
function format(template, params = {}, plural = FRENCH_PLURAL) {
  return template.replace(PLACEHOLDER, (whole, name, one, other) => {
    const value = params[name];
    if (value === void 0) {
      return whole;
    }
    if (one === void 0 || other === void 0) {
      return String(value);
    }
    return plural(Number(value)) === "one" ? one : other;
  });
}
function formatSeconds(seconds) {
  const total = Math.max(0, Math.round(seconds));
  if (total < 60) {
    return `${total}\xA0s`;
  }
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor(total % 3600 / 60);
  const rest2 = total % 60;
  if (hours > 0) {
    return `${hours}\xA0h\xA0${String(minutes).padStart(2, "0")}`;
  }
  return rest2 === 0 ? `${minutes}\xA0min` : `${minutes}\xA0min\xA0${String(rest2).padStart(2, "0")}`;
}
function normalize(text) {
  return text.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[’'`]/g, " ").replace(/[^a-z0-9]+/g, " ").trim();
}

