var ASSUMED_EQUIPMENT = ["floor", "wall"];
var LOADABLE_EQUIPMENT = ["dumbbells", "kettlebell", "barbell", "backpack", "weight-vest", "medicine-ball", "sandbag"];
var isEquipment = (value) => EQUIPMENT.includes(value);
var IMPLIES = {
  "two-chairs": ["chair"],
  bench: ["step"],
  box: ["step"],
  "dip-bars": ["parallettes"]
};
function inventory(owned = [], assumed = ASSUMED_EQUIPMENT) {
  const loads = /* @__PURE__ */ new Map();
  const declared = [];
  for (const item2 of [...assumed, ...owned]) {
    const id = typeof item2 === "string" ? item2 : item2.id;
    if (!isEquipment(id)) {
      throw new Error(`Mat\xE9riel inconnu : \xAB ${id} \xBB`);
    }
    declared.push(id);
    if (typeof item2 !== "string" && item2.loads) {
      loads.set(id, [.../* @__PURE__ */ new Set([...loads.get(id) ?? [], ...item2.loads.filter((load) => load > 0)])].sort((a, b) => a - b));
    }
  }
  const ids = /* @__PURE__ */ new Set();
  const add = (id) => {
    if (ids.has(id)) {
      return;
    }
    ids.add(id);
    for (const implied of IMPLIES[id] ?? []) {
      add(implied);
    }
  };
  declared.forEach(add);
  const sorted = EQUIPMENT.filter((id) => ids.has(id));
  return {
    has: (id) => ids.has(id),
    loadsOf: (id) => loads.get(id) ?? [],
    ids: sorted
  };
}
function satisfies(need2, available) {
  return (need2 ?? []).every((group) => group.length === 0 || group.some((id) => available.has(id)));
}
function equipmentUsed(need2, available) {
  return (need2 ?? []).flatMap((group) => {
    const found = group.find((id) => available.has(id));
    return found ? [found] : [];
  });
}

